example.code:
from slack_sdk import WebClient

client = WebClient(token="xoxb-your-bot-token")

# 1. 기본 텍스트 메시지 전송
response = client.chat_postMessage(
    channel="#general",
    text="배포가 완료되었습니다."
)

# 2. Block Kit으로 버튼 포함 메시지
client.chat_postMessage(
    channel="#deployments",
    text="PR 병합 대기 중",
    blocks=[
        {
            "type": "section",
            "text": {"type": "mrkdwn", "text": "*PR #123* 병합 준비 완료"}
        },
        {
            "type": "actions",
            "elements": [
                {"type": "button", "text": {"type": "plain_text", "text": "병합"},
                 "action_id": "merge_button", "style": "primary"},
                {"type": "button", "text": {"type": "plain_text", "text": "취소"},
                 "action_id": "cancel_button"}
            ]
        }
    ]
)
